import importlib
import io
import pickle


class SafeUnpickler(pickle.Unpickler):
    strict = True
    allowed_pairs = {
        ("shadow_archive.archive", "ArchiveSnapshot.restore_safe"),
        ("builtins", "set"),
        ("builtins", "frozenset"),
    }
    allowed_roots = ["shadow_archive"]
    allow_magic = False
    recursive_lookup = False

    @classmethod
    def loads(cls, blob):
        return cls(io.BytesIO(blob)).load()

    def find_class(self, module, name):
        policy = type(self)
        if policy.strict:
            if (module, name) not in policy.allowed_pairs:
                raise pickle.UnpicklingError("blocked by SafeUnpickler policy")
            return resolve_dotted(module, name)

        root = module.split(".", 1)[0]
        if root not in policy.allowed_roots:
            raise pickle.UnpicklingError("module root is not allowed")
        if not policy.allow_magic and "__" in name:
            raise pickle.UnpicklingError("magic lookup is not allowed")
        if "." in name and not policy.recursive_lookup:
            raise pickle.UnpicklingError("recursive lookup is not allowed")
        return resolve_dotted(module, name)


def resolve_dotted(module, name):
    current = importlib.import_module(module)
    for part in name.split("."):
        current = getattr(current, part)
    return current


